dashboard.definition:
{
    "title": "Daily state of health",
    "description": "Engineering view of the latest DH Daily SoH report (07:00, index=data_health source=dh:soh) plus the live unregistered list (spec §8.4).",
    "inputs": {},
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "-8d",
                        "latest": "+1d"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_soh": {
            "type": "ds.search",
            "name": "Latest daily report (dh:soh)",
            "options": {
                "query": "search index=data_health source=\"dh:soh\" sourcetype=stash earliest=-8d latest=+1d | eval report_time=tonumber(report_time) | eventstats max(report_time) as dh_latest | where report_time==dh_latest | fields - dh_latest"
            }
        },
        "ds_when": {
            "type": "ds.chain",
            "name": "Report time",
            "options": {
                "extend": "ds_soh",
                "query": "| stats max(report_time) as t | eval report=if(isnull(t), \"no report yet (DH Daily SoH report runs at 07:00)\", strftime(t, \"%Y-%m-%d %H:%M\")) | table report"
            }
        },
        "ds_mttr": {
            "type": "ds.chain",
            "name": "MTTR",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"mttr\" | eval mttr=if(isnull(value) OR value==\"\", \"-\", tostring(tonumber(value), \"duration\")) | table mttr outages open_outages"
            }
        },
        "ds_outages": {
            "type": "ds.chain",
            "name": "Outages",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"outage\" | eval start=strftime(tonumber(start), \"%Y-%m-%d %H:%M\"), end=if(tonumber(open)==1, \"still open\", strftime(tonumber(end), \"%Y-%m-%d %H:%M\")), duration=tostring(tonumber(value), \"duration\") | sort 0 -value | table item start end duration | rename item AS entity_id"
            }
        },
        "ds_flapping": {
            "type": "ds.chain",
            "name": "Flapping",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"flapping\" | sort 0 -value | table item value | rename item AS entity_id, value AS transitions_24h"
            }
        },
        "ds_never": {
            "type": "ds.chain",
            "name": "Never seen and invalid profiles",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"never_seen\" OR section==\"invalid_profile\" | eval detail=if(section==\"never_seen\", \"expected since \".strftime(tonumber(value), \"%Y-%m-%d %H:%M\"), value) | table section item detail | rename item AS entity_id"
            }
        },
        "ds_unreg": {
            "type": "ds.search",
            "name": "Unregistered (live)",
            "options": {
                "query": "| `dh_ui_unregistered(dh_expected, dh_state_fast, dh_state_slow, dh_baseline, now())`"
            }
        },
        "ds_fwd": {
            "type": "ds.chain",
            "name": "Forwarders",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"fwd_version\" OR section==\"fwd_disconnected\" | eval last_seen=strftime(tonumber(last_seen), \"%Y-%m-%d %H:%M\") | table section item version last_seen | rename item AS host"
            }
        },
        "ds_lag": {
            "type": "ds.chain",
            "name": "Lag p95",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"lag\" | sort 0 -value | table item value day | rename item AS entity_id, value AS lag_p95_secs"
            }
        },
        "ds_volume": {
            "type": "ds.chain",
            "name": "Volume flags",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"volume\" | sort 0 -value | table item value min_ratio | rename item AS entity_id, value AS flagged_hours"
            }
        },
        "ds_lic_pct": {
            "type": "ds.chain",
            "name": "Licence usage",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"licence\" AND item==\"usage_pct\" | eval usage=value.\"%\" | table usage"
            }
        },
        "ds_lic_days": {
            "type": "ds.chain",
            "name": "Licence expiry",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"licence\" AND item==\"expires_days\" | table value"
            }
        },
        "ds_skipped": {
            "type": "ds.chain",
            "name": "Skipped searches",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"skipped\" | sort 0 -value | table item value | rename item AS search, value AS skipped_24h"
            }
        },
        "ds_mutes": {
            "type": "ds.chain",
            "name": "Mutes",
            "options": {
                "extend": "ds_soh",
                "query": "| where section==\"mute_expiring\" OR section==\"mute_active\" | eval until=strftime(tonumber(value), \"%Y-%m-%d %H:%M\") | table section item until reason ticket set_by | rename item AS entity_id"
            }
        }
    },
    "visualizations": {
        "viz_when": {
            "type": "splunk.singlevalue",
            "title": "Report of",
            "dataSources": {
                "primary": "ds_when"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"report\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_mttr": {
            "type": "splunk.singlevalue",
            "title": "MTTR (24 h)",
            "dataSources": {
                "primary": "ds_mttr"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"mttr\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_outages_n": {
            "type": "splunk.singlevalue",
            "title": "Outages (24 h)",
            "dataSources": {
                "primary": "ds_mttr"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"outages\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_open_n": {
            "type": "splunk.singlevalue",
            "title": "Still open",
            "dataSources": {
                "primary": "ds_mttr"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"open_outages\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_lic_pct": {
            "type": "splunk.singlevalue",
            "title": "Licence used yesterday",
            "dataSources": {
                "primary": "ds_lic_pct"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"usage\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_lic_days": {
            "type": "splunk.singlevalue",
            "title": "Licence expires in (days)",
            "dataSources": {
                "primary": "ds_lic_days"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"value\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_outages": {
            "type": "splunk.table",
            "title": "Outages in 24 h with durations",
            "dataSources": {
                "primary": "ds_outages"
            },
            "options": {
                "count": 25
            }
        },
        "viz_flapping": {
            "type": "splunk.table",
            "title": "Flapping (3 or more transitions in 24 h)",
            "dataSources": {
                "primary": "ds_flapping"
            },
            "options": {
                "count": 25
            }
        },
        "viz_never": {
            "type": "splunk.table",
            "title": "Never seen, and invalid profiles",
            "dataSources": {
                "primary": "ds_never"
            },
            "options": {
                "count": 25
            }
        },
        "viz_unreg": {
            "type": "splunk.table",
            "title": "Unregistered (live: seen in 7 d, not expected)",
            "dataSources": {
                "primary": "ds_unreg"
            },
            "options": {
                "count": 25
            }
        },
        "viz_fwd": {
            "type": "splunk.table",
            "title": "Forwarders off the expected version or disconnected",
            "dataSources": {
                "primary": "ds_fwd"
            },
            "options": {
                "count": 25
            }
        },
        "viz_lag": {
            "type": "splunk.table",
            "title": "Lag p95 (sourcetypes at or above 60 s)",
            "dataSources": {
                "primary": "ds_lag"
            },
            "options": {
                "count": 25
            }
        },
        "viz_volume": {
            "type": "splunk.table",
            "title": "Volume flags (24 h)",
            "dataSources": {
                "primary": "ds_volume"
            },
            "options": {
                "count": 25
            }
        },
        "viz_skipped": {
            "type": "splunk.table",
            "title": "Skipped searches (24 h)",
            "dataSources": {
                "primary": "ds_skipped"
            },
            "options": {
                "count": 25
            }
        },
        "viz_mutes": {
            "type": "splunk.table",
            "title": "Active and expiring mutes",
            "dataSources": {
                "primary": "ds_mutes"
            },
            "options": {
                "count": 25
            }
        }
    },
    "layout": {
        "type": "grid",
        "options": {
            "width": 1440,
            "height": 1680
        },
        "structure": [
            {
                "item": "viz_when",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_outages_n",
                "type": "block",
                "position": {
                    "x": 240,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_open_n",
                "type": "block",
                "position": {
                    "x": 480,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_mttr",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_lic_pct",
                "type": "block",
                "position": {
                    "x": 960,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_lic_days",
                "type": "block",
                "position": {
                    "x": 1200,
                    "y": 0,
                    "w": 240,
                    "h": 120
                }
            },
            {
                "item": "viz_outages",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 120,
                    "w": 960,
                    "h": 340
                }
            },
            {
                "item": "viz_flapping",
                "type": "block",
                "position": {
                    "x": 960,
                    "y": 120,
                    "w": 480,
                    "h": 340
                }
            },
            {
                "item": "viz_never",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 460,
                    "w": 720,
                    "h": 300
                }
            },
            {
                "item": "viz_fwd",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 460,
                    "w": 720,
                    "h": 300
                }
            },
            {
                "item": "viz_unreg",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 760,
                    "w": 1440,
                    "h": 320
                }
            },
            {
                "item": "viz_lag",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 1080,
                    "w": 720,
                    "h": 300
                }
            },
            {
                "item": "viz_volume",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 1080,
                    "w": 720,
                    "h": 300
                }
            },
            {
                "item": "viz_skipped",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 1380,
                    "w": 720,
                    "h": 300
                }
            },
            {
                "item": "viz_mutes",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 1380,
                    "w": 720,
                    "h": 300
                }
            }
        ]
    }
}
